    public List selectNodes(String xpath) {
    	ArrayList list = new ArrayList();
    	Iterator iterator = iteratePointers(xpath);
    	while (iterator.hasNext()) {
			Pointer pointer = (Pointer) iterator.next();
			list.add(pointer.getNode());
		}
		return list;

